using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Text;using System.Windows.Forms;

sealed partial class FormasForm {
 readonly ComboBox mathListening=new ComboBox(),mathNoteTarget=new ComboBox();
 readonly TextBox mathBookTitle=new TextBox(),mathBookFeedback=new TextBox(),mathNoteName=new TextBox(),mathNoteDescription=new TextBox(),mathNoteHint=new TextBox(),mathNoteComment=new TextBox();
 readonly Label mathNoteAnchor=new Label{AutoSize=true};
 Dictionary<string,object> mathBook;readonly Dictionary<string,Dictionary<string,object>> mathBooks=new Dictionary<string,Dictionary<string,object>>();string mathEditingKey="",mathBookPath="";long mathBookRequest;
 static readonly string[] MathReadingKeys={"tokens","digits","rows","columns","steps","development"};
 void TeachingText(FlowLayoutPanel p,string label,TextBox field,int max,bool multiple){Paragraph(p,label);field.AccessibleName=label;field.Width=650;field.MaxLength=max;field.Multiline=multiple;if(multiple){field.Height=80;field.ScrollBars=ScrollBars.Vertical;}p.Controls.Add(field);}
 void BuildTeaching(FlowLayoutPanel p){
  Paragraph(p,"Lección y anotaciones. Son textos del autor, no verificaciones matemáticas. Guarda la lección FAO para enviarla y devolver propuestas.");
  MathButton(p,"Probar ecuación con notas del profesor",()=>MathExample("ecuacion-con-anotaciones.fao"));MathButton(p,"Probar fracciones con notas del profesor",()=>MathExample("fracciones-con-anotaciones.fao"));
  Select(p,"Cómo escuchar la lección",mathListening,new string[]{"Exploración libre: notas a petición","Entrenamiento guiado: fragmento y nombre de nota","Repaso de notas: avance manual"},0,()=>{Stop();mathAnnounce.Checked=false;mathAnnounce.Enabled=mathListening.SelectedIndex==1;});
  TeachingText(p,"Título de la lección",mathBookTitle,160,false);TeachingText(p,"Alternativas o comentarios generales para devolver al profesor",mathBookFeedback,6000,true);
  Select(p,"Elemento que quieres anotar o consultar",mathNoteTarget,new string[]{"Fragmento seleccionado","Vista general del plano","Punto actual del plano"},0,()=>{});MathButton(p,"Editar anotación del elemento elegido",MathEditNote);mathNoteAnchor.Text="Sin anotación en edición";p.Controls.Add(mathNoteAnchor);
  TeachingText(p,"Nombre breve de la anotación",mathNoteName,160,false);TeachingText(p,"Explicación de la anotación",mathNoteDescription,3000,true);TeachingText(p,"Pista de la anotación",mathNoteHint,3000,true);TeachingText(p,"Respuesta, duda o propuesta sobre este elemento",mathNoteComment,3000,true);
  MathButton(p,"Guardar anotación en la lección",()=>{MathSaveNote();Say("Anotación guardada en memoria. Guarda la lección FAO para conservarla al cerrar.");});MathButton(p,"Leer nombre de la nota",()=>MathReadNote(0));MathButton(p,"Leer explicación de la nota",()=>MathReadNote(1));MathButton(p,"Pedir pista de la nota",()=>MathReadNote(2));MathButton(p,"Leer comentario del elemento",()=>MathReadNote(3));MathButton(p,"Eliminar anotación elegida",()=>{string key=MathTarget();MathNotes().Remove(key);if(key==mathEditingKey)MathClearNote();Say("Anotación eliminada de la lección.");});
  MathButton(p,"Guardar lección FAO para compartir",MathSaveBook);MathButton(p,"Abrir lección FAO",MathOpenBook);
 }
 Dictionary<string,object> MathNotes(){if(mathBook==null)throw new InvalidOperationException("Prepara primero una expresión.");return (Dictionary<string,object>)mathBook["notes"];}
 string MathTarget(){if(!MathCurrent())throw new InvalidOperationException("Prepara la expresión antes de editar notas.");if(mathNoteTarget.SelectedIndex==1)return "plane:"+mathPlane.SelectedIndex;if(mathNoteTarget.SelectedIndex==2)return "point:"+mathPlane.SelectedIndex+":"+((int)Math.Floor((double)mathX.Value*10+.5)).ToString(CultureInfo.InvariantCulture)+":"+((int)Math.Floor((double)mathY.Value*10+.5)).ToString(CultureInfo.InvariantCulture);if(mathChoices.SelectedIndex<0)throw new InvalidOperationException("Selecciona primero un fragmento.");return "fragment:"+mathMode.SelectedIndex+":"+mathChoices.SelectedIndex;}
 string MathAnchorLabel(string key){var p=key.Split(':');if(p[0]=="fragment")return new string[]{"Símbolos","Cifras","Filas","Columnas","Procedimiento","Pizarra progresiva"}[int.Parse(p[1])]+", fragmento "+(int.Parse(p[2])+1);string plane=Convert.ToString(mathPlane.Items[int.Parse(p[1])]);return p[0]=="plane"?plane+", vista general":plane+", equis "+(int.Parse(p[2])/10m).ToString(CultureInfo.CurrentCulture)+", ye "+(int.Parse(p[3])/10m).ToString(CultureInfo.CurrentCulture); }
 void MathClearNote(){mathEditingKey="";mathNoteName.Clear();mathNoteDescription.Clear();mathNoteHint.Clear();mathNoteComment.Clear();mathNoteAnchor.Text="Sin anotación en edición";}
 void MathSaveNote(){if(mathEditingKey.Length==0)throw new InvalidOperationException("Primero elige Editar anotación del elemento elegido.");var notes=MathNotes();if(!notes.ContainsKey(mathEditingKey)&&notes.Count>=128)throw new InvalidOperationException("Máximo 128 anotaciones por lección.");notes[mathEditingKey]=new Dictionary<string,object>{{"name",mathNoteName.Text},{"description",mathNoteDescription.Text},{"hint",mathNoteHint.Text},{"comment",mathNoteComment.Text}};}
 void MathEditNote(){string target=MathTarget();if(mathEditingKey.Length>0)MathSaveNote();mathEditingKey=target;object raw;var note=MathNotes().TryGetValue(target,out raw)?(Dictionary<string,object>)raw:null;var fields=new TextBox[]{mathNoteName,mathNoteDescription,mathNoteHint,mathNoteComment};var keys=new string[]{"name","description","hint","comment"};for(int i=0;i<fields.Length;i++)fields[i].Text=note==null?"":Convert.ToString(note[keys[i]]);mathNoteAnchor.Text="Editando "+MathAnchorLabel(target)+". La nota seguirá vinculada a este destino aunque te muevas.";Say("Anotación lista para editar.");}
 string MathNote(string key,int level){object raw;if(!MathNotes().TryGetValue(key,out raw))return "No hay anotación guardada para este elemento.";string value=Convert.ToString(((Dictionary<string,object>)raw)[new string[]{"name","description","hint","comment"}[level]]);return value.Length==0?"Este nivel de la anotación está vacío.":value;}
 void MathReadNote(int level){if(mathEditingKey.Length>0)MathSaveNote();MathSpeak(MathNote(MathTarget(),level));}
 void MathCaptureBook(){if(mathBook==null)return;if(mathEditingKey.Length>0)MathSaveNote();mathBook["title"]=mathBookTitle.Text;mathBook["feedback"]=mathBookFeedback.Text;mathBook["cursor"]=new Dictionary<string,object>{{"mode",mathMode.SelectedIndex},{"position",Math.Max(0,mathChoices.SelectedIndex)},{"plane",mathPlane.SelectedIndex},{"x",mathX.Value},{"y",mathY.Value}};}
 void MathSetBook(Dictionary<string,object> imported){
  if(mathBook!=null){MathCaptureBook();mathBooks[Convert.ToString(mathBook["expression"])]=mathBook;}
  string expression=MathValue("expression");Dictionary<string,object> previous;
  if(imported!=null)mathBook=imported;else if(mathBooks.TryGetValue(expression,out previous))mathBook=previous;else{var readings=new Dictionary<string,object>();foreach(string key in MathReadingKeys)readings[key]=MathItems(key).ToArray();mathBook=new Dictionary<string,object>{{"schema","formas-lesson-v1"},{"title","Lección de matemáticas"},{"feedback",""},{"expression",expression},{"readings",readings},{"notes",new Dictionary<string,object>()},{"cursor",new Dictionary<string,object>{{"mode",5},{"position",0},{"plane",0},{"x",0},{"y",0}}}};}
  if(mathBooks.Count>20){string oldest=null;foreach(string key in mathBooks.Keys){oldest=key;break;}if(oldest!=null)mathBooks.Remove(oldest);}MathClearNote();mathBookTitle.Text=Convert.ToString(mathBook["title"]);mathBookFeedback.Text=Convert.ToString(mathBook["feedback"]);foreach(var pair in (Dictionary<string,object>)mathBook["readings"])mathData[pair.Key]=pair.Value;
 }
 void MathSaveBook(){if(!MathCurrent())return;MathCaptureBook();using(var dialog=new SaveFileDialog()){dialog.Filter="Lección Formas al oído|*.fao";dialog.FileName="leccion-formas.fao";if(dialog.ShowDialog(this)!=DialogResult.OK)return;string data=json.Serialize(mathBook);if(Encoding.UTF8.GetByteCount(data)>262144)throw new InvalidDataException("La lección supera 256 KB.");mathBookPath=dialog.FileName;Send("MATH_BOOK_SAVE|"+B64(data)+"|"+(++mathBookRequest));}}
 void MathOpenBook(){using(var dialog=new OpenFileDialog()){dialog.Filter="Lección Formas al oído|*.fao;*.json|Todos los archivos|*.*";if(dialog.ShowDialog(this)!=DialogResult.OK)return;if(new FileInfo(dialog.FileName).Length>262144)throw new InvalidDataException("La lección supera 256 KB.");Stop();mathRequestedInput=mathInput.Text;Send("MATH_BOOK_LOAD|"+B64(File.ReadAllText(dialog.FileName,Encoding.UTF8))+"|"+(++mathRequest));}}
 void MathExample(string name){Stop();mathRequestedInput=mathInput.Text;Send("MATH_BOOK_LOAD|"+B64(File.ReadAllText(Path.Combine(home,"teaching",name),Encoding.UTF8))+"|"+(++mathRequest));}
 int teachingSmokeStage;
 bool SmokeTeaching(){
  string key="fragment:5:0";
  if(teachingSmokeStage==0){mathMode.SelectedIndex=5;mathChoices.SelectedIndex=0;MathEditNote();mathNoteName.Text="Equilibrio";mathNoteDescription.Text="Operar en ambos miembros";mathNoteHint.Text="Conserva la igualdad";mathNoteComment.Text="Profesor: separar este paso";MathSaveNote();mathBookTitle.Text="Piloto docente";mathBookFeedback.Text="Prefiero menos palabras por etapa";mathListening.SelectedIndex=0;MathMove(1);if(!mathReadout.Text.Contains("seleccionado"))throw new Exception("Free exploration narrated unexpectedly");mathChoices.SelectedIndex=0;mathListening.SelectedIndex=1;MathRead();if(!mathReadout.Text.Contains("Nota: Equilibrio"))throw new Exception("Guided note missing");mathListening.SelectedIndex=2;MathRead();if(!mathReadout.Text.Contains("Operar en ambos miembros"))throw new Exception("Review note missing");MathNotes()["fragment:5:2"]=new Dictionary<string,object>{{"name","Segunda nota"},{"description","Continuar"},{"hint",""},{"comment",""}};MathMove(1);if(mathChoices.SelectedIndex!=2)throw new Exception("Review did not skip unannotated step");MathMove(-1);if(mathChoices.SelectedIndex!=0)throw new Exception("Review did not return to annotation");var stages=MathItems("development").ToArray();stages[1]="Etapa del profesor: restamos tres en ambos lados";((Dictionary<string,object>)mathBook["readings"])["development"]=stages;MathCaptureBook();mathBookPath=Path.Combine(storage,"lesson-pilot.fao");if(File.Exists(mathBookPath))File.Delete(mathBookPath);Send("MATH_BOOK_SAVE|"+B64(json.Serialize(mathBook))+"|"+(++mathBookRequest));teachingSmokeStage=1;return false;}
  if(teachingSmokeStage==1){if(!File.Exists(mathBookPath))return false;string saved=File.ReadAllText(mathBookPath,Encoding.UTF8);if(!saved.Contains("Profesor: separar este paso"))throw new Exception("Feedback missing from file");mathBookTitle.Text="Cambio temporal";mathRequestedInput=mathInput.Text;Send("MATH_BOOK_LOAD|"+B64(saved)+"|"+(++mathRequest));teachingSmokeStage=2;return false;}
  if(mathBookTitle.Text!="Piloto docente")return false;if(MathNote(key,0)!="Equilibrio"||!MathItems("development")[1].Contains("Etapa del profesor")||mathBookFeedback.Text!="Prefiero menos palabras por etapa")throw new Exception("Teaching file roundtrip failed");if(mathListening.SelectedIndex!=2||mathNarration.Checked)throw new Exception("Imported file changed voice preferences");return true;
 }
 void ReceiveTeaching(string[] a){if(a[0]=="MATHBOOKSAVE"){if(a.Length<3||a[2]!=mathBookRequest.ToString(CultureInfo.InvariantCulture))return;File.WriteAllText(mathBookPath,Decode(a[1]),new UTF8Encoding(false));Say("Lección FAO guardada. Puedes enviarla como archivo y devolverla con tus comentarios.");return;}if(a.Length<3||a[2]!=mathRequest.ToString(CultureInfo.InvariantCulture))return;var all=json.Deserialize<Dictionary<string,object>>(Decode(a[1]));var book=(Dictionary<string,object>)all["book"];mathData=(Dictionary<string,object>)all["exercise"];MathSetBook(book);mathInput.Text=MathValue("expression");mathGrid.Text=MathValue("grid").Replace("\n",Environment.NewLine);var cursor=(Dictionary<string,object>)book["cursor"];mathMode.SelectedIndex=Convert.ToInt32(cursor["mode"]);MathRefresh();mathChoices.SelectedIndex=Convert.ToInt32(cursor["position"]);mathPlane.SelectedIndex=Convert.ToInt32(cursor["plane"]);MathPlane();mathX.Value=Convert.ToDecimal(cursor["x"],CultureInfo.InvariantCulture);mathY.Value=Convert.ToDecimal(cursor["y"],CultureInfo.InvariantCulture);MathAt(false,false);Say("Lección abierta. Voz y modo de escucha conservan tus preferencias. Las notas y etapas son contenido del autor.");}
}
